"""Safe Dynamic Python Script Execution Engine for SolidWorks."""

from __future__ import annotations

import math
import sys
import time
import traceback
from typing import Any, Dict
from ..com_adapter.base import BaseSolidWorksAdapter, CADResult


class PythonScriptExecutor:
    """Executes arbitrary dynamic Python CAD scripts generated by the CAD client with live SolidWorks context."""

    def __init__(self, adapter: BaseSolidWorksAdapter):
        self.adapter = adapter

    def execute(self, script_code: str) -> CADResult:
        """Execute a Python CAD script against the active SolidWorks adapter."""
        if hasattr(self.adapter, "execute_raw_python"):
            return self.adapter.execute_raw_python(script_code)

        # Fallback runner using adapter methods
        scope_globals = {
            "adapter": self.adapter,
            "math": math,
            "time": time,
        }
        scope_locals: Dict[str, Any] = {}

        try:
            exec(script_code, scope_globals, scope_locals)
            self.adapter.rebuild()
            return CADResult(
                success=True,
                message="Python CAD script executed successfully.",
                data={"locals": {k: str(v) for k, v in scope_locals.items() if not k.startswith("_")}},
            )
        except Exception as e:
            return CADResult(
                success=False,
                message=f"Script execution error: {str(e)}",
                error=traceback.format_exc(),
            )
